def find_path(graph, start, goal):
    if start == goal:
        return [start]
    visited = set()

    def recursive_find_path(current, path):
        visited.add(current)
        path.append(current)
        if current == goal:
            return path
        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                next_path = recursive_find_path(neighbor, path.copy())
                if next_path:
                    return next_path
        path.pop()
        return None
    return recursive_find_path(start, [])

